Below is a small Flask app with password login, persistent SQLite storage, and append-only note versions. Each visit has its own note history.

Save this as `app.py`:

```python
import hmac
import os
import secrets
import sqlite3
from datetime import date
from functools import wraps

from flask import (
    Flask, abort, g, redirect, render_template_string,
    request, session, url_for,
)
from werkzeug.security import check_password_hash, generate_password_hash

app = Flask(__name__)

# Keep these values stable across restarts.
app.secret_key = os.environ["APP_SECRET"]
PASSWORD_HASH = os.environ["APP_PASSWORD_HASH"]
DB_PATH = os.environ.get("DB_PATH", "physio.db")

app.config.update(
    SESSION_COOKIE_HTTPONLY=True,
    SESSION_COOKIE_SAMESITE="Lax",
    # Set to "1" when serving over HTTPS.
    SESSION_COOKIE_SECURE=os.environ.get("HTTPS") == "1",
)


def db():
    if "db" not in g:
        g.db = sqlite3.connect(DB_PATH)
        g.db.row_factory = sqlite3.Row
        g.db.execute("PRAGMA foreign_keys = ON")
    return g.db


@app.teardown_appcontext
def close_db(error):
    connection = g.pop("db", None)
    if connection is not None:
        connection.close()


def init_db():
    with app.app_context():
        db().executescript("""
            CREATE TABLE IF NOT EXISTS visits (
                id INTEGER PRIMARY KEY,
                patient_name TEXT NOT NULL,
                visit_date TEXT NOT NULL
            );

            CREATE TABLE IF NOT EXISTS note_versions (
                id INTEGER PRIMARY KEY,
                visit_id INTEGER NOT NULL REFERENCES visits(id),
                content TEXT NOT NULL,
                created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP
            );
        """)
        db().commit()


def csrf_token():
    if "csrf" not in session:
        session["csrf"] = secrets.token_urlsafe(32)
    return session["csrf"]


app.jinja_env.globals["csrf_token"] = csrf_token


@app.before_request
def check_csrf():
    if request.method == "POST":
        expected = session.get("csrf", "")
        supplied = request.form.get("csrf", "")
        if not expected or not hmac.compare_digest(expected, supplied):
            abort(400, "Invalid form token")


def login_required(fn):
    @wraps(fn)
    def wrapped(*args, **kwargs):
        if not session.get("logged_in"):
            return redirect(url_for("login"))
        return fn(*args, **kwargs)
    return wrapped


STYLE = """
<style>
  body { font: 16px sans-serif; max-width: 800px; margin: 2rem auto;
         padding: 0 1rem; line-height: 1.5; }
  input, textarea { box-sizing: border-box; width: 100%; padding: .5rem; }
  textarea { min-height: 12rem; }
  button { padding: .5rem 1rem; cursor: pointer; }
  label { display: block; margin-top: 1rem; }
  pre { white-space: pre-wrap; overflow-wrap: anywhere; font: inherit; }
  .version { border-top: 1px solid #ccc; padding: .5rem 0; }
  .error { color: #a00; }
</style>
"""


def page(template, **values):
    return render_template_string(STYLE + template, **values)


@app.route("/login", methods=["GET", "POST"])
def login():
    error = None
    if request.method == "POST":
        if check_password_hash(PASSWORD_HASH, request.form.get("password", "")):
            session.clear()
            session["logged_in"] = True
            return redirect(url_for("index"))
        error = "Incorrect password."
    return page("""
        <h1>Practice notes: login</h1>
        {% if error %}<p class="error">{{ error }}</p>{% endif %}
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <label>Password <input type="password" name="password" required autofocus></label>
          <p><button>Log in</button></p>
        </form>
    """, error=error)


@app.post("/logout")
@login_required
def logout():
    session.clear()
    return redirect(url_for("login"))


@app.get("/")
@login_required
def index():
    visits = db().execute("""
        SELECT id, patient_name, visit_date
        FROM visits ORDER BY visit_date DESC, id DESC
    """).fetchall()
    return page("""
        <h1>Patient visits</h1>
        <form method="post" action="{{ url_for('logout') }}">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <button>Log out</button>
        </form>
        <p><a href="{{ url_for('new_visit') }}">Add a visit</a></p>
        <ul>
          {% for visit in visits %}
            <li><a href="{{ url_for('visit', visit_id=visit.id) }}">
              {{ visit.patient_name }} — {{ visit.visit_date }}
            </a></li>
          {% else %}
            <li>No visits yet.</li>
          {% endfor %}
        </ul>
    """, visits=visits)


@app.route("/visits/new", methods=["GET", "POST"])
@login_required
def new_visit():
    error = None
    if request.method == "POST":
        name = request.form.get("patient_name", "").strip()
        visit_date = request.form.get("visit_date", "")
        content = request.form.get("content", "").strip()
        try:
            date.fromisoformat(visit_date)
            valid_date = True
        except ValueError:
            valid_date = False

        if name and content and valid_date:
            connection = db()
            with connection:
                cursor = connection.execute(
                    "INSERT INTO visits (patient_name, visit_date) VALUES (?, ?)",
                    (name, visit_date),
                )
                connection.execute(
                    "INSERT INTO note_versions (visit_id, content) VALUES (?, ?)",
                    (cursor.lastrowid, content),
                )
            return redirect(url_for("visit", visit_id=cursor.lastrowid))
        error = "Enter a patient name, valid date, and note."

    return page("""
        <p><a href="{{ url_for('index') }}">← Visits</a></p>
        <h1>New visit</h1>
        {% if error %}<p class="error">{{ error }}</p>{% endif %}
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <label>Patient name
            <input name="patient_name" required value="{{ request.form.get('patient_name', '') }}">
          </label>
          <label>Visit date
            <input type="date" name="visit_date" required
                   value="{{ request.form.get('visit_date', today) }}">
          </label>
          <label>Note
            <textarea name="content" required>{{ request.form.get('content', '') }}</textarea>
          </label>
          <p><button>Save visit</button></p>
        </form>
    """, error=error, today=date.today().isoformat())


@app.route("/visits/<int:visit_id>", methods=["GET", "POST"])
@login_required
def visit(visit_id):
    connection = db()
    visit_record = connection.execute(
        "SELECT * FROM visits WHERE id = ?", (visit_id,)
    ).fetchone()
    if visit_record is None:
        abort(404)

    error = None
    if request.method == "POST":
        content = request.form.get("content", "").strip()
        if content:
            with connection:
                connection.execute(
                    "INSERT INTO note_versions (visit_id, content) VALUES (?, ?)",
                    (visit_id, content),
                )
            return redirect(url_for("visit", visit_id=visit_id))
        error = "The note cannot be empty."

    versions = connection.execute("""
        SELECT id, content, created_at FROM note_versions
        WHERE visit_id = ? ORDER BY id DESC
    """, (visit_id,)).fetchall()

    return page("""
        <p><a href="{{ url_for('index') }}">← Visits</a></p>
        <h1>{{ visit.patient_name }}</h1>
        <p>Visit date: {{ visit.visit_date }}</p>
        <h2>Edit note</h2>
        <p>Saving creates a new version; previous versions remain below.</p>
        {% if error %}<p class="error">{{ error }}</p>{% endif %}
        <form method="post">
          <input type="hidden" name="csrf" value="{{ csrf_token() }}">
          <textarea name="content" required>{{ request.form.get('content', versions[0].content) }}</textarea>
          <p><button>Save new version</button></p>
        </form>
        <h2>Version history</h2>
        {% for version in versions %}
          <div class="version">
            <strong>Version {{ version.id }} — {{ version.created_at }} UTC</strong>
            <pre>{{ version.content }}</pre>
          </div>
        {% endfor %}
    """, visit=visit_record, versions=versions, error=error)


init_db()

if __name__ == "__main__":
    app.run()
```

### Run it

```bash
pip install Flask

# Generate and save these values securely; reuse them on subsequent starts.
export APP_SECRET="$(python -c 'import secrets; print(secrets.token_hex(32))')"
export APP_PASSWORD_HASH="$(python -c 'from getpass import getpass; from werkzeug.security import generate_password_hash; print(generate_password_hash(getpass("Password: ")))')"

python app.py
```

Open `http://127.0.0.1:5000`. Notes persist in `physio.db` in the working directory.

**Before using real patient data:** this is a basic prototype, not a complete clinical-records system. Use HTTPS, set `HTTPS=1`, restrict server and database access, encrypt and test backups, and assess applicable health-privacy requirements. It has a single shared login and lacks features such as login throttling, individual user accounts, and audit logging.

